INSERT INTO `ausw_saetze` (`id`, `satz`) VALUES
(1, 'braucht selten Unterstützung bei der Anwendung neuer Lernmethoden'),
(2, 'Selbstständigkeit hat sich in den letzten Wochen deutlich verbessert'),
(3, 'zeigt meistens Engagement bei der Vorbereitung auf die Nachhilfestunden'),
(4, 'kann Wissen nur bedingt in Diagrammen, Skizzen oder Mindmaps visualisieren'),
(5, 'gespr ging in die hose! betrachtete es als angriff'),
(6, 'kann mittlerweile zuvor schwierige Aufgaben teilweise bewältigen'),
(7, 'kann nur wenig geschickt zwischen Aufgaben wechseln, die unterschiedliche Lernbereiche abdecken'),
(8, 'kann Gelerntes gut auf andere Fächer oder den Alltag übertragen'),
(9, 'kann den eigenen Lösungsweg jederzeit nachvollziehbar schriftlich präsentieren'),
(10, 'Eigenständige Arbeit und versteht das Thema jedoch hat Problem beim Aufgabenverständnis.'),
(11, 'kann sein Wissen in Testsituationen bzw. unter Druck nur eingeschränkt anwenden'),
(12, 'Dreisatz wird langsam / Einh.-Aufg. lösen'),
(13, 'die Lernfortschritte des Schülers im Rahmen der Nachhilfe haben sich etwas verbessert'),
(14, 'reagiert interessiert auf neue Herausforderungen'),
(15, 'Lernmaterialien und Notizen sind sehr strukturiert'),
(16, 'gelingt es regelmäßig, eigenständig Lösungsansätze umzusetzen, die mit dem Nachhilfelehrer besprochen wurden'),
(17, 'konnte durch die Nachhilfe seine Noten im Unterricht etwas verbessern'),
(18, 'die Lernstrategien des Schülers haben sich in den vergangenen Wochen teilweise verbessert'),
(19, 'kann gut mit Stress umgehen, wenn Aufgaben schwieriger werden'),
(20, 'kann nur sporadisch den Operatoren der Aufgabenstellung entsprechend eine Antwort formulieren'),
(21, 'die Einstellung des Schülers zum Lernen hat sich in letzter Zeit verbessert'),
(22, 'erledigt seine Hausaufgaben, die er durch die Nachhilfe erhält, zuverlässig'),
(23, 'kann erlerntes Wissen auch bei unangekündigten Tests zuverlässig abrufen'),
(24, 'kann Wissen, das in den letzten Nachhilfestunden thematisiert wurde, meistens abrufen'),
(25, 'Aufgabenänderungen stressen den Schüler nur wenig'),
(26, 'zeigt nur selten Geduld mit sich selbst und den eigenen Lernfortschritten'),
(27, 'das Zeitmanagement des Schülers hat sich verbessert'),
(28, 'kann sein Vorwissen meistens reaktivieren, um neue Informationen besser zu verstehen'),
(29, 'kann sein Wissen in Testsituationen genauso gut wie im Unterricht anwenden'),
(30, 'kann bereits erlerntes Wissen meistens auf neue Themen anwenden'),
(31, 'strebt oftmals danach, Aufgaben selbstständig, also ohne Hilfe, zu lösen'),
(32, 'ist meistens in der Lage, Aufgaben ohne Hilfe zu bearbeiten'),
(33, 'lernt weitgehend aus gemachten Fehlern und erkennt Fehler und Korrekturen während des Unterrichts weitgehend als Chance zum Lernen'),
(34, 'hat geplante Zeit überwiegend sinnvoll genutzt'),
(35, 'ist überwiegend in der Lage, die Fehler einer fremden Lösung zu begründen und zu berichtigen');
