INSERT INTO `mtr_rueckkopplung_lehrkraft_tn` (`id`, `ue_zuweisung_teilnehmer_id`, `teilnehmer_id`, `datum`, `erfasst_am`, `lehrkraft`, `fach`, `thema`, `rueckmeldung`, `mitarbeit`, `absprachen`, `selbststaendigkeit`, `konzentration`, `fleiss`, `lernfortschritt`, `beherrscht_thema`, `transferdenken`, `basiswissen`, `vorbereitet`, `themenauswahl`, `materialien`, `methodenvielfalt`, `individualisierung`, `aufforderung`, `emotions`, `bemerkungen`, `metr_kognition`, `metr_sozial`, `metr_affektiv`, `metr_metakog`, `metr_kohaerenz`) VALUES
(1, 176, 20, '2025-11-03', '2025-11-05 12:47:56', 'Thiele, Dipl.-Ing. Olaf - geändert: 04.11.25', 'PHY', 'Prüfungsvorbereitung: BLF', 'Schaff, Luise (10 GYM) Protokoll Noten Extras Protokoll filter_listadd ! Luise kommt nicht in den Herbstferien stellt manchmal Fragen, die ein tieferes Verständnis für das aktuelle Thema zeigen hat zuletzt deutlich von der individuellen Unterstützung in der Nachhilfe profitiert setzt Prioritäten bei Lernaufgaben sehr sinnvoll braucht selten Unterstützung bei der Anwendung neuer Lernmethoden gibt nur manchmal zu erkennen, wenn er ein Problem mit einer Aufgabenstellung hat', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0.2, 0),
(2, 130, 20, '2025-10-27', '2025-11-05 12:47:56', 'Thiele, Dipl.-Ing. Olaf - geändert: 28.10.25', 'MAT', 'Weitere Themen: Stochastik Üb 2', 'konnte Wissen in der heutigen Stunde weitgehend festigen Selbstständigkeit hat sich in den letzten Wochen deutlich verbessert kann sich sehr gut auf eine Aufgabe konzentrieren, auch wenn diese als uninteressant empfunden wird braucht selten Unterstützung bei der Anwendung neuer Lernmethoden vermeidet die Wiederholung von zuvor gemachten Fehlern erfolgreich', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0.2, 0),
(3, 122, 20, '2025-10-24', '2025-11-05 12:47:56', 'Thiele, Dipl.-Ing. Olaf - geändert: 25.10.25', 'PHY', 'Prüfungsvorbereitung: BLF', 'fühlt sich ziemlich sicher bei der Anwendung des Gelernten Einstellung zum Lernen hat sich in letzter Zeit stark verbessert ist sehr offen für andere Lösungsansätze kann die Lernzeit für mehrere Tests normalerweise effektiv einteilen kann umfangreiches Wissen in der Regel sinnvoll zusammenfassen nM Teil B Staudamm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0.4, 0, 0.6, 0.2, 0),
(4, 106, 20, '2025-10-20', '2025-11-05 12:47:56', 'Thiele, Dipl.-Ing. Olaf', 'PHY', 'Weitere Themen: quadrErg', 'ist überwiegend in der Lage, die Fehler einer fremden Lösung zu begründen und zu berichtigen Einstellung zum Lernen hat sich in letzter Zeit verbessert gibt oft zu erkennen, wenn er etwas nicht verstanden hat schafft normalerweise alle Aufgaben in einer Klassenarbeit oder Leistungskontrollen in der dafür angesetzten Zeit erreicht in der Regel vereinbarte Lernziele Wachstum/Zerfall', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0.2, 0, 0.2, 0.2, 0),
(5, 77, 20, '2025-09-29', '2025-11-05 12:47:56', 'Thiele, Dipl.-Ing. Olaf', 'PHY', 'Weitere Themen: BLF', 'hat sich in Bereichen, die zuvor als schwierig identifiziert wurden, erstaunlich verbessert hat in letzter Zeit ein deutlich besseres Verständnis für die Anforderungen der Lehrkraft in der Schule entwickelt ergreift oft die Möglichkeit, Hilfsmittel (z.B. Taschenrechner, Tafelwerk, Wörterbuch) zu nutzen benötigt fast keine Zeit, um nach einer Ablenkung die Arbeit wieder aufzunehmen kommuniziert seine Gedanken und Ideen teilweise verständlich und nachvollziehbar', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0.2, 0, 0.2, 0.2),
(6, 72, 20, '2025-09-26', '2025-11-05 12:47:56', 'Thiele, Dipl.-Ing. Olaf', 'PHY', 'Prüfungsvorbereitung: BLF', 'beherrscht die spezifischen Fachbegriffe zuverlässig Vertrauen in die eigenen Fähigkeiten hat sich in den letzten Wochen stark verbessert wird von schwierigeren Aufgaben immerzu motiviert arbeitet überwiegend in einem angemessenen Tempo erreicht in der Regel vereinbarte Lernziele', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0.2, 0.2, 0),
(7, 51, 20, '2025-09-22', '2025-11-05 12:47:56', 'Thiele, Dipl.-Ing. Olaf - geändert: 23.09.25', 'MAT', 'Weitere Themen: trigFkt', 'nutzt oft die vermittelten Methoden Vertrauen in die eigenen Fähigkeiten hat sich in den letzten Wochen verbessert kann den eigenen Lösungsweg häufig nachvollziehbar schriftlich präsentieren bittet aktiv um Feedback kann umfangreiches Wissen in der Regel sinnvoll zusammenfassen', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0.2, 0.2, 0, 0.2, 0.2),
(8, 43, 20, '2025-09-19', '2025-11-05 12:47:56', 'Thiele, Dipl.-Ing. Olaf - geändert: 20.09.25', 'PHY', 'Trigonometrie: Üb', 'beherrscht die spezifischen Fachbegriffe zuverlässig Notenentwicklung in den letzten Wochen unverändert kann Wissen, das in den letzten Nachhilfestunden thematisiert wurde, meistens abrufen hält Fristen für Hausaufgaben und Projekte sehr konsequent ein reagiert interessiert auf neue Herausforderungen', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0.2, 0, 0),
(9, 36, 20, '2025-09-08', '2025-11-05 12:47:56', 'Thiele, Dipl.-Ing. Olaf - geändert: 09.09.25', 'MAT', 'Quadratische Funktion/Gleichung: BLF T B', 'Newtonsche Gesetze: VorbLK kann erlerntes Wissen auch bei unangekündigten Tests zuverlässig abrufen Geschwindigkeit beim Lösen von Aufgaben hat sich in den letzten Stunden ohne Qualitätsverlust erhöht kann den eigenen Lösungsweg häufig nachvollziehbar mündlich präsentieren versucht sich oftmals erneut an Aufgaben, mit denen es kurz zuvor Probleme gab ist oft fähig, Aufgaben ohne direkte Anleitung zu beginnen', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0.2, 0, 0, 0, 0.2),
(10, 33, 2, '2025-09-15', '2025-11-09 15:29:42', 'Thiele, Dipl.-Ing. Olaf - geändert: 16.09.25', 'MAT', 'Trigonometrie: Satz des Pythagoras und Co-/Sinus', 'Geometrie: rwDr ist überwiegend in der Lage, fremde Lösungen zu prüfen und enthaltene Fehler zu erkennen Fähigkeit zum Verstehen und Analysieren komplexer Sachverhalte hat sich über die letzten Wochen verbessert arbeitet konsequent auf langfristige Ziele hin, bei denen sofortige Erfolge gelegentlich ausbleiben muss selten an formale Vorgehensweisen erinnert werden kann Feedback erfolgreich in den eigenen Lernprozess integrieren', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0.4, 0.2, 0, 0.2, 0),
(11, 39, 2, '2025-09-17', '2025-11-09 15:29:42', 'Thiele, Dipl.-Ing. Olaf - geändert: 18.09.25', 'MAT', 'Trigonometrie: Satz des Pythagoras und Co-/Sinus', 'Geometrie: SdP fühlt sich ziemlich sicher bei der Anwendung des Gelernten Einfluss der Nachhilfe auf die gesamte schulische Entwicklung sehr positiv zeigt sich zielstrebig beim Erreichen von Lernzielen ist zugänglich für spontane Wiederholungen teilt sich die eigene Lernzeit angemessen ein', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0.2, 0, 0.2, 0.2, 0),
(12, 47, 2, '2025-09-22', '2025-11-09 15:29:42', 'Thiele, Dipl.-Ing. Olaf', 'MAT', 'Trigonometrie: Satz des Pythagoras und Co-/Sinus', 'Geometrie: SdP/HSatz kann sein Wissen in Testsituationen genauso gut wie im Unterricht anwenden wendet die in der Nachhilfe gelernten Strategien meistens auch außerhalb der Nachhilfestunden an kann gut Zusammenhänge zwischen verschiedenen Informationen erkennen kommuniziert seine Gedanken und Ideen verständlich und nachvollziehbar kann gut nach einem festgelegten Zeitplan lernen', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0.4, 0.2, 0, 0.2, 0.2),
(13, 75, 2, '2025-09-29', '2025-11-09 15:29:42', 'Thiele, Dipl.-Ing. Olaf', 'MAT', 'Trigonometrie: Satz des Pythagoras und Co-/Sinus', 'Geometrie: SdP/WinkelFkt ist überwiegend in der Lage, fremde Lösungen zu prüfen und enthaltene Fehler zu erkennen Beteiligung am Unterricht hat sich verbessert vermeidet Flüchtigkeitsfehler überwiegend kann komplexe Informationen einigermaßen verständlich mit eigenen Worten erklären braucht gelegentlich Unterstützung bei der Anwendung neuer Lösungsansätze', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0.2, 0),
(14, 88, 2, '2025-10-01', '2025-11-09 15:29:42', 'Thiele, Dipl.-Ing. Olaf', 'MAT', 'Trigonometrie: Satz des Pythagoras und Co-/Sinus', 'Geometrie: TrgFkt nutzt oft die vermittelten Methoden Zuverlässigkeit bei den Hausaufgaben hat sich verbessert ist oft fähig, Aufgaben ohne direkte Anleitung zu beenden kann sich gut auf eine Aufgabe konzentrieren, auch wenn diese als uninteressant empfunden wird kann umfangreiches Wissen in der Regel sinnvoll zusammenfassen', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0.2, 0, 0, 0.2, 0),
(15, 14, 16, '2025-09-11', '2025-11-09 15:31:38', 'Thiele, Dipl.-Ing. Olaf', 'MAT', 'Weitere Themen: VorbBLF', 'kann Gelerntes gut auf andere Fächer oder den Alltag übertragen Notenentwicklung in den letzten Wochen unverändert offen für neue Strategien oder Herangehensweisen beim Lernen, besonders nach Misserfolgen strebt oftmals danach, Aufgaben selbstständig, also ohne Hilfe, zu lösen kann gut nach einem festgelegten Zeitplan lernen', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0.2, 0, 0.2, 0.2, 0.2),
