INSERT INTO `_frzk_orverlust_kapiteltext_bausteine` (`id`, `kontext`, `profil_id`, `text`) VALUES
(1, 'profil_definition', 1, 'Dieses Profil beschreibt Lernende mit hoher affektiver Beteiligung bei gleichzeitig geringer fachlicher und sozialer Strukturierung.'),
(2, 'interpretation', 1, 'Bedeutung entsteht primär über emotionale Resonanz, nicht über begriffliche Ordnung.'),
(3, 'didaktik', 1, 'Weitere Motivationssteigerung ist nicht angezeigt; stattdessen ist Strukturierung zentral.'),
(4, 'fehler', 1, 'Ein klassischer Fehler ist zusätzliche emotionale Aktivierung ohne kognitive Anbindung.'),
(5, 'intervention', 1, 'Didaktisch sinnvoll ist der Pfad Affekt → Struktur → Begriff.'),
(6, 'profil_definition', 2, 'Dieses Profil ist durch hohe kognitive Strukturierung bei geringer affektiver und sozialer Einbindung gekennzeichnet.'),
(7, 'interpretation', 2, 'Bedeutung wird über formale Begriffe erzeugt, bleibt jedoch emotional distanziert.'),
(8, 'didaktik', 2, 'Nicht weitere Strukturierung, sondern affektive und soziale Anschlussfähigkeit ist zentral.'),
(9, 'fehler', 2, 'Überstrukturierung ohne Bedeutungsgewinn.'),
(10, 'intervention', 2, 'Struktur → Affekt → Begriff.'),
(11, 'profil_definition', 3, 'Sozial getragene Profile erleben Lernen primär als Beziehungsgeschehen.'),
(12, 'interpretation', 3, 'Soziale Sicherheit ersetzt fachliche Struktur.'),
(13, 'didaktik', 3, 'Soziale Prozesse müssen fachlich gerahmt werden.'),
(14, 'fehler', 3, 'Mehr Gruppenarbeit ohne fachliche Fixierung.'),
(15, 'intervention', 3, 'Sozial → Struktur → Begriff.'),
(16, 'profil_definition', 4, 'Dieses Profil weist eine hohe Integration aller Dimensionen auf.'),
(17, 'interpretation', 4, 'Es liegt eine stabile Bedeutungsdichte vor.'),
(18, 'didaktik', 4, 'Stabilisieren statt intervenieren.'),
(19, 'fehler', 4, 'Überdidaktisierung stabiler Prozesse.'),
(20, 'intervention', 4, 'Reflexion und Transfer.'),
(21, 'profil_definition', 5, 'Fragmentierte Profile zeigen keine stabile epistemische Achse.'),
(22, 'interpretation', 5, 'Bedeutung bleibt episodisch und instabil.'),
(23, 'didaktik', 5, 'Reduktion und Fokussierung sind zentral.'),
(24, 'fehler', 5, 'Gleichzeitige Mehrfachintervention.'),
(25, 'intervention', 5, 'Ein Hub – eine Achse.');
INSERT INTO `_frzk_orverlust_profil_didaktische_ableitung` (`profil_id`, `zentrale_empfehlung`, `fokus_im_unterricht`, `empfohlene_lehrkraftstrategie`) VALUES
(1, 'Nicht weiter motivieren.', 'Struktur und Begriffe.', 'Affekt → Struktur → Begriff.'),
(2, 'Nicht weiter strukturieren.', 'Affekt & Soziales.', 'Emotionale Hubs einsetzen.'),
(3, 'Soziales nicht weiter verstärken.', 'Fachliche Ordnung.', 'Sozial → Struktur.'),
(4, 'Keine Intervention.', 'Stabilisierung.', 'Reflexion.'),
(5, 'Reduktion.', 'Eine Achse.', 'Einen Hub stabilisieren.');
